import{_ as a,o as n,a as p,b as c}from"./app.DKoEZOcr.js";const l="/ascendc.github.io/pr/5487/assets/mem_merge.xJ3nZG0P.png",h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"算子实践参考","link":"/guide/operator_practice/document_structure"},{"text":"SIMT算子性能优化","link":"/guide/operator_practice/simt_operator_optimization/simt_operator_optimization"},{"text":"内存访问","link":"/guide/operator_practice/simt_operator_optimization/memory_access/memory_access_merge"},{"text":"访存合并","link":"/guide/operator_practice/simt_operator_optimization/memory_access/memory_access_merge"}]},"headers":[],"relativePath":"guide/operator_practice/simt_operator_optimization/memory_access/memory_access_merge.md","filePath":"guide/operator_practice/simt_operator_optimization/memory_access/memory_access_merge.md","lastUpdated":1787050286000}'),t={name:"guide/operator_practice/simt_operator_optimization/memory_access/memory_access_merge.md"};function e(o,s,i,r,d,w){return n(),p("div",null,[...s[0]||(s[0]=[c('<div><article class="markdown-body"><h1>访存合并</h1><p>【优先级】高</p><p>【描述】SIMT编程模式下，一个Warp内的相邻线程（thread）通常同时发起GM访问请求。若这些线程访问的GM地址连续，硬件可以将访问请求合并，从而提高GM带宽利用率；若相邻线程访问的GM地址跨行或离散分布，则难以形成访存合并，算子执行耗时会明显增加。对于转置、重排、gather/scatter等算子，需要结合数据排布和线程映射关系进行分析，尽量让同一个Warp内相邻线程在同一条访存指令上访问连续地址。</p><p><strong>图1</strong> 访存合并对比示意图</p><img src="'+l+`"><p>访存合并优化适用于两类场景：第一类是数据本身在GM上连续，只是相邻thread被分配处理的数据不连续，导致同一个Warp内相邻线程访问了不连续地址，此时优先调整数据切分方式，使Warp内相邻thread访问连续数据；第二类是算子功能包含转置、重排等布局变换，单纯调整切分方式很难同时保证GM读写都连续，此时考虑引入Unified Buffer（UB）内存空间作为中转，利用UB完成不连续的数据重排过程，从而尽量保证GM侧访问连续。</p><ul><li><p>优化数据切分实现访存合并</p><p>【样例介绍】以<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/03_simt_api/00_introduction/01_gather/general_gather">Gather算子</a>为例，算子按行从输入中取数，计算公式可以表示为<code>output[row, col] = input[index[row], col]</code>。输出矩阵每一行内部的列方向数据在GM上连续，优化切分时应让同一个Warp内相邻线程尽量访问同一行内的相邻列，而不是只保证单个线程内部连续。</p><p>【反例】按thread切分数据，每个thread处理连续的一行数据。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">type_data</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">type_idx</span><span class="o">&gt;</span>
<span class="n">__global__</span><span class="w"> </span><span class="n">__launch_bounds__</span><span class="p">(</span><span class="n">MAX_THREAD_COUNT</span><span class="p">)</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">gather_custom</span><span class="p">(</span>
<span class="w">    </span><span class="n">type_data</span><span class="o">*</span><span class="w"> </span><span class="n">input</span><span class="p">,</span>
<span class="w">    </span><span class="n">type_idx</span><span class="o">*</span><span class="w"> </span><span class="n">index</span><span class="p">,</span>
<span class="w">    </span><span class="n">type_data</span><span class="o">*</span><span class="w"> </span><span class="n">gather_output</span><span class="p">,</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">in_width</span><span class="p">,</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">index_total_length</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="kt">int32_t</span><span class="w"> </span><span class="n">out_row</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">blockIdx</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">blockDim</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">threadIdx</span><span class="p">.</span><span class="n">x</span><span class="p">;</span>

<span class="w">    </span><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">out_row</span><span class="w"> </span><span class="o">&gt;=</span><span class="w"> </span><span class="n">index_total_length</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="k">return</span><span class="p">;</span>
<span class="w">    </span><span class="p">}</span>

<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">in_row</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">index</span><span class="p">[</span><span class="n">out_row</span><span class="p">];</span>
<span class="w">    </span><span class="kt">int</span><span class="w"> </span><span class="n">input_idx</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">in_row</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">in_width</span><span class="p">;</span>
<span class="w">    </span><span class="kt">int</span><span class="w"> </span><span class="n">output_idx</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">out_row</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">in_width</span><span class="p">;</span>
<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">int32_t</span><span class="w"> </span><span class="n">col</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">col</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">in_width</span><span class="p">;</span><span class="w"> </span><span class="n">col</span><span class="o">++</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">gather_output</span><span class="p">[</span><span class="n">output_idx</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">input</span><span class="p">[</span><span class="n">input_idx</span><span class="p">];</span>
<span class="w">        </span><span class="n">input_idx</span><span class="w"> </span><span class="o">+=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span>
<span class="w">        </span><span class="n">output_idx</span><span class="w"> </span><span class="o">+=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div><p>上述实现把输出行分配给不同thread，每个thread在<code>for</code>循环内连续处理一整行数据。从单个thread视角看，<code>input_idx</code>和<code>output_idx</code>都是连续递增的；但SIMT访存合并的关键是同一个Warp内相邻thread在同一条访存指令上访问的地址连续。在该实现中，同一个Warp内的相邻thread分别处理不同的<code>out_row</code>，虽然单个thread内部访问连续，但Warp内访问不连续，GM访存难以合并。</p><p>以输入shape为20001×1023，index长度为核数乘以2048为例，线程块总数与物理核数相等，每个线程块启动2048个线程，反例算子执行该用例的性能数据如下：</p><table><thead><tr><th align="center">Task Duration(us)</th><th align="center">aiv_time(us)</th><th align="center">aiv_total_cycles</th><th align="center">aiv_vec_time(us)</th><th align="center">aiv_vec_ratio</th><th align="center">aiv_scalar_time(us)</th><th align="center">aiv_scalar_ratio</th></tr></thead><tbody><tr><td align="center">4886.076</td><td align="center">4535.644</td><td align="center">7483813.083</td><td align="center">4535.178</td><td align="center">0.999</td><td align="center">0.454</td><td align="center">0.001</td></tr></tbody></table><p>【正例】按Thread Block切分输出数据，Warp内相邻thread访问连续地址。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">type_data</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">type_idx</span><span class="o">&gt;</span>
<span class="n">__global__</span><span class="w"> </span><span class="n">__launch_bounds__</span><span class="p">(</span><span class="n">MAX_THREAD_COUNT</span><span class="p">)</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">gather_custom</span><span class="p">(</span>
<span class="w">    </span><span class="n">type_data</span><span class="o">*</span><span class="w"> </span><span class="n">input</span><span class="p">,</span>
<span class="w">    </span><span class="n">type_idx</span><span class="o">*</span><span class="w"> </span><span class="n">index</span><span class="p">,</span>
<span class="w">    </span><span class="n">type_data</span><span class="o">*</span><span class="w"> </span><span class="n">gather_output</span><span class="p">,</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">in_width</span><span class="p">,</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">output_total_size</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">start</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">blockIdx</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">blockDim</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">threadIdx</span><span class="p">.</span><span class="n">x</span><span class="p">;</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">stride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">blockDim</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">gridDim</span><span class="p">.</span><span class="n">x</span><span class="p">;</span>

<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">idx</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">start</span><span class="p">;</span><span class="w"> </span><span class="n">idx</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">output_total_size</span><span class="p">;</span><span class="w"> </span><span class="n">idx</span><span class="w"> </span><span class="o">+=</span><span class="w"> </span><span class="n">stride</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">out_row</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">idx</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="n">in_width</span><span class="p">;</span>
<span class="w">        </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">out_col</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">idx</span><span class="w"> </span><span class="o">-</span><span class="w"> </span><span class="n">out_row</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">in_width</span><span class="p">;</span>
<span class="w">        </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">in_row</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">index</span><span class="p">[</span><span class="n">out_row</span><span class="p">];</span>
<span class="w">        </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">input_i</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">in_row</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">in_width</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">out_col</span><span class="p">;</span>
<span class="w">        </span><span class="n">gather_output</span><span class="p">[</span><span class="n">idx</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">input</span><span class="p">[</span><span class="n">input_i</span><span class="p">];</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div><p>上述实现将输出矩阵按一维线性地址组织，并让每个Thread Block覆盖一段连续的输出元素。对于同一次循环迭代，Thread Block内thread的<code>idx</code>连续递增，同一个Warp内相邻thread会访问连续的<code>gather_output[idx]</code>。当这些<code>idx</code>位于同一个输出行内时，<code>out_row</code>相同，<code>out_col</code>连续递增，<code>in_row = index[out_row]</code>，因此<code>in_row</code>也相同，输入访问<code>input[in_row * in_width + out_col]</code>的地址也是连续的，输入和输出都可以实现访存合并。</p><p>在正例的代码中，每个thread在整个过程中并非处理一段连续数据，而是以<code>blockDim.x * gridDim.x</code>为步长处理多个元素。也就是说，单个thread多次迭代访问的数据是跳跃的；但在每一次迭代中，Warp内相邻thread访问的是连续地址。SIMT访存合并的收益来自Warp维度的连续访问，因此这种切分方式通常比“每个thread处理一整段连续数据”更能发挥GM带宽优势。</p><p>配套的Thread Block切分也从按<code>index_total_length</code>切分调整为按<code>output_total_size</code>切分，使线程数量覆盖真实输出元素规模：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="kt">bool</span><span class="w"> </span><span class="nf">block_split</span><span class="p">(</span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">output_total_size</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="o">&amp;</span><span class="n">blocks_per_grid</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="o">&amp;</span><span class="n">threads_per_block</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">real_core_num</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="k">auto</span><span class="o">&amp;</span><span class="w"> </span><span class="n">platformInfoMgr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">platform_ascendc</span><span class="o">::</span><span class="n">PlatformAscendCManager</span><span class="o">::</span><span class="n">GetInstance</span><span class="p">();</span>
<span class="w">    </span><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">platformInfoMgr</span><span class="w"> </span><span class="o">==</span><span class="w"> </span><span class="nb">nullptr</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">std</span><span class="o">::</span><span class="n">cout</span><span class="w"> </span><span class="o">&lt;&lt;</span><span class="w"> </span><span class="s">&quot;[ERROR] Get platform info failed, please check device status.&quot;</span><span class="w"> </span><span class="o">&lt;&lt;</span><span class="w"> </span><span class="n">std</span><span class="o">::</span><span class="n">endl</span><span class="p">;</span>
<span class="w">        </span><span class="k">return</span><span class="w"> </span><span class="nb">false</span><span class="p">;</span>
<span class="w">    </span><span class="p">}</span>
<span class="w">    </span><span class="n">real_core_num</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">platformInfoMgr</span><span class="o">-&gt;</span><span class="n">GetCoreNumAiv</span><span class="p">();</span>
<span class="w">    </span><span class="n">threads_per_block</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">std</span><span class="o">::</span><span class="n">min</span><span class="p">(</span><span class="n">output_total_size</span><span class="p">,</span><span class="w"> </span><span class="n">MAX_THREAD_COUNT</span><span class="p">);</span>
<span class="w">    </span><span class="n">blocks_per_grid</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">(</span><span class="n">output_total_size</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">threads_per_block</span><span class="w"> </span><span class="o">-</span><span class="w"> </span><span class="mi">1</span><span class="p">)</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="n">threads_per_block</span><span class="p">;</span>
<span class="w">    </span><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">blocks_per_grid</span><span class="w"> </span><span class="o">&gt;</span><span class="w"> </span><span class="n">real_core_num</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">blocks_per_grid</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">real_core_num</span><span class="p">;</span>
<span class="w">        </span><span class="n">threads_per_block</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">MAX_THREAD_COUNT</span><span class="p">;</span>
<span class="w">    </span><span class="p">}</span>
<span class="w">    </span><span class="k">return</span><span class="w"> </span><span class="nb">true</span><span class="p">;</span>
<span class="p">}</span>
</code></pre></div><p>正例算子实现访存合并，执行该用例的性能数据如下：</p><table><thead><tr><th align="center">Task Duration(us)</th><th align="center">aiv_time(us)</th><th align="center">aiv_total_cycles</th><th align="center">aiv_vec_time(us)</th><th align="center">aiv_vec_ratio</th><th align="center">aiv_scalar_time(us)</th><th align="center">aiv_scalar_ratio</th></tr></thead><tbody><tr><td align="center">866.103</td><td align="center">864.080</td><td align="center">1425731.861</td><td align="center">863.590</td><td align="center">0.999</td><td align="center">0.478</td><td align="center">0.001</td></tr></tbody></table><p>从Task Duration看，访存合并后的执行耗时为866.103us，相比优化前的4886.076us，下降约82.3%。这说明优化前的主要瓶颈来自Warp内相邻thread访问的GM地址不连续，调整数据切分后，相邻thread在同一次访存指令上访问相邻元素，GM访存效率得到明显改善。</p></li><li><p>引入UB中转实现访存合并</p><p>【样例介绍】以<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/03_simt_api/03_best_practices/00_memory_optimizations/matrix_transpose_practice">矩阵转置</a>为例，输入矩阵shape为1024×1024，数据类型为<code>float</code>。直接全局内存转置版本按一维线性地址遍历元素，逐元素写入转置后的GM位置，Thread Block数量固定为硬件vector core数，每个Thread Block启动2048个线程；UB中转版本将矩阵划分为32×32的tile，Thread Block数量按<code>ceil(total_tiles / 2)</code>设置，每个Thread Block启动2048个线程同时处理两个tile，<code>threadIdx.x</code>方向的32个thread对应tile内同一行的32个连续元素，先将tile连续读入UB，再按转置方向读取并连续写回GM。</p><p>【反例】直接按照转置公式写回GM。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="kt">uint32_t</span><span class="w"> </span><span class="n">row</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="n">width</span><span class="p">;</span>
<span class="kt">uint32_t</span><span class="w"> </span><span class="n">col</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">-</span><span class="w"> </span><span class="n">row</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">width</span><span class="p">;</span>
<span class="c1">// input(row,col) -&gt; output(col,row)</span>
<span class="n">output</span><span class="p">[</span><span class="n">col</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">height</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">row</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">input</span><span class="p">[</span><span class="n">i</span><span class="p">];</span>
</code></pre></div><p>上述实现按一维线性地址遍历输入矩阵，每个线程在循环中处理多个<code>input[i]</code>，并写入转置位置<code>output[col * height + row]</code>。读取输入时，同一个Warp内相邻thread的<code>i</code>连续递增，<code>input[i]</code>地址连续，GM读访问可以合并；写回输出时，同一Warp内相邻thread的<code>i</code>递增对应<code>col</code>递增（同一行内），转置后的写地址<code>col * height + row</code>按<code>height</code>步长跨行分布，相邻thread会写到输出矩阵的不同行，GM写访问难以形成合并访存。</p><p>在1024×1024矩阵转置样例中，该实现对应Case 2，性能数据如下：</p><table><thead><tr><th align="center">Task Duration(μs)</th><th align="center">aiv_time(μs)</th><th align="center">aiv_total_cycles</th><th align="center">aiv_vec_time(μs)</th><th align="center">aiv_vec_ratio</th><th align="center">aiv_scalar_time(μs)</th><th align="center">aiv_scalar_ratio</th></tr></thead><tbody><tr><td align="center">36.337</td><td align="center">34.022</td><td align="center">56136.2</td><td align="center">33.568</td><td align="center">0.987</td><td align="center">0.442</td><td align="center">0.013</td></tr></tbody></table><p>【正例】使用UB中转，将非连续GM写转换为UB内转置读。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">float</span><span class="w"> </span><span class="n">tile</span><span class="p">[</span><span class="n">TILES_PER_BLOCK</span><span class="p">][</span><span class="n">TILE_DIM</span><span class="p">][</span><span class="n">TILE_DIM</span><span class="p">];</span>
<span class="p">...</span>
<span class="kt">uint32_t</span><span class="w"> </span><span class="n">local_tile</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">threadIdx</span><span class="p">.</span><span class="n">y</span><span class="w"> </span><span class="o">&gt;&gt;</span><span class="w"> </span><span class="mi">5</span><span class="p">;</span><span class="w">       </span><span class="c1">// 0或1，区分Thread Block内两个tile</span>
<span class="kt">uint32_t</span><span class="w"> </span><span class="n">ty</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">threadIdx</span><span class="p">.</span><span class="n">y</span><span class="w"> </span><span class="o">&amp;</span><span class="w"> </span><span class="p">(</span><span class="n">TILE_DIM</span><span class="w"> </span><span class="o">-</span><span class="w"> </span><span class="mi">1</span><span class="p">);</span>
<span class="kt">uint32_t</span><span class="w"> </span><span class="n">tx</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">threadIdx</span><span class="p">.</span><span class="n">x</span><span class="p">;</span>
<span class="p">...</span>
<span class="n">tile</span><span class="p">[</span><span class="n">local_tile</span><span class="p">][</span><span class="n">ty</span><span class="p">][</span><span class="n">tx</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">input</span><span class="p">[</span><span class="n">x_index</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">y_index</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">width</span><span class="p">];</span>
<span class="n">asc_syncthreads</span><span class="p">();</span>
<span class="n">output</span><span class="p">[</span><span class="n">x_index</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">y_index</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">height</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">tile</span><span class="p">[</span><span class="n">local_tile</span><span class="p">][</span><span class="n">tx</span><span class="p">][</span><span class="n">ty</span><span class="p">];</span>
</code></pre></div><p>上述实现先将输入矩阵按32×32的tile连续读入UB，再交换输出tile坐标，使同一个Warp按输出矩阵的行方向连续写回GM。这样处理后，GM读取阶段按输入矩阵行方向连续访问，GM写回阶段按输出矩阵行方向连续访问；转置造成的非连续访问被转移为UB内部的转置方向读取。每个Thread Block启动2048个线程，通过<code>local_tile = threadIdx.y &gt;&gt; 5</code>区分Block内的两个tile，<code>threadIdx.y=0..31</code>处理第一个tile，<code>threadIdx.y=32..63</code>处理第二个tile。</p><p>在1024×1024矩阵转置样例中，该实现对应Case 3，性能数据如下：</p><table><thead><tr><th align="center">Task Duration(μs)</th><th align="center">aiv_time(μs)</th><th align="center">aiv_total_cycles</th><th align="center">aiv_vec_time(μs)</th><th align="center">aiv_vec_ratio</th><th align="center">aiv_scalar_time(μs)</th><th align="center">aiv_scalar_ratio</th></tr></thead><tbody><tr><td align="center">28.190</td><td align="center">2.896</td><td align="center">4778.1</td><td align="center">2.712</td><td align="center">0.938</td><td align="center">0.172</td><td align="center">0.058</td></tr></tbody></table><p>从Task Duration看，使用UB中转后的执行耗时为28.190μs，相比直接全局内存转置的36.337μs，下降约22.4%。这说明该转置场景的主要收益来自将原本不连续的GM写访问转换为UB内转置读，使GM读写两侧都尽量保持连续访问；虽然引入UB会带来一次中转和线程同步开销，但在该用例中，GM写访问合并带来的收益超过了这些额外开销。</p></li></ul><p>【总结】SIMT算子进行访存优化时，应优先分析同一个Warp内相邻thread在同一条访存指令下访问的GM地址是否连续。常用优化方法包括：一是调整数据切分方式，将连续的数据区域分配给Thread Block和Warp，使每次迭代中Warp内相邻thread访问连续地址，单个thread可通过stride处理剩余数据以覆盖完整输出；二是引入UB进行数据中转和布局重排，将原本不连续的GM访问转换为UB内的重排访问，从而尽量保证GM读写都沿连续方向进行。</p></article></div>`,1)])])}const u=a(t,[["render",e]]);export{h as __pageData,u as default};
